  'This course introduces forensic science and criminalistics as evidence-centered scientific practice in the American criminal justice system. Students learn how evidence is recognized, documented, collected, analyzed, interpreted, reported, and presented in court. The course emphasizes scientific validity, quality systems, uncertainty, bias control, ethics, legal admissibility, and the limits of forensic conclusions.',
  $fscrjson${"slug": "forensic-science-criminalistics", "title": "Forensic Science / Criminalistics", "description": "This course introduces forensic science and criminalistics as evidence-centered scientific practice in the American criminal justice system. Students learn how evidence is recognized, documented, collected, analyzed, interpreted, reported, and presented in court. The course emphasizes scientific validity, quality systems, uncertainty, bias control, ethics, legal admissibility, and the limits of forensic conclusions.", "topics": [{"id": "2e6819c9-8bfb-41ae-a428-de2e83968d62", "type": "topic", "title": "Foundations of Forensic Science, Criminalistics, and the Justice System", "description": "Frame forensic science as applied scientific measurement used in legal investigation, adjudication, exclusion, and accountability.", "children": [{"id": "46429bab-f21b-4d62-a610-5af71d989896", "type": "subtopic", "title": "Field scope and disciplines", "children": [{"id": "c53f27ea-0869-4d52-b816-b6058a89ecc5", "type": "concept", "title": "Criminalistics, forensic biology, forensic chemistry, trace evidence, latent prints, firearms, toxicology, documents, and digital evidence"}, {"id": "139c7b76-5383-4b98-ac42-c3e0d48a6c03", "type": "concept", "title": "Laboratory disciplines versus medical examiner, coroner, pathology, anthropology, nursing, psychiatry, and engineering roles"}, {"id": "47dc442d-fa04-42fa-8f38-056d176a8f88", "type": "concept", "title": "Investigation, intelligence, screening, confirmatory testing, interpretation, reporting, and testimony"}], "description": "Students learn what criminalistics includes and where it sits within forensic science."}, {"id": "ddca3cc1-c5ba-4847-85b9-ed85ee1f33f9", "type": "subtopic", "title": "Scientific method in legal context", "children": [{"id": "5a21ca1a-668f-4fbb-8226-0fa303fd5782", "type": "concept", "title": "Observation, hypothesis, sampling, testing, controls, reproducibility, peer review, and falsifiability"}, {"id": "771d00dc-8adc-4019-b2a5-5d405651e7ec", "type": "concept", "title": "Sensitivity, specificity, accuracy, precision, bias, uncertainty, and limitations"}, {"id": "87cfb049-4ca4-4216-b3ff-83f74d4cbfab", "type": "concept", "title": "Legal relevance, probative value, admissibility, and fact-finder communication"}], "description": "The gist is to distinguish scientific inference from investigative intuition."}, {"id": "3dcd888b-95a9-437d-82ec-627d830bce2d", "type": "subtopic", "title": "American forensic system", "children": [{"id": "484eb31d-694e-4b3d-96df-fa0b575faa56", "type": "concept", "title": "Federal, state, local, tribal, and private forensic service providers"}, {"id": "663d4e27-e12b-4ca0-a8bc-8308ceebf2cf", "type": "concept", "title": "DOJ, FBI Laboratory, DEA, ATF, NIJ, NIST, OSAC, accrediting bodies, and professional societies"}, {"id": "42832c3b-b180-4f42-adcc-28a2d389a420", "type": "concept", "title": "Backlogs, resources, independence, quality culture, and public trust"}], "description": "Students see how crime labs, police, prosecutors, defenders, courts, and standards bodies interact."}]}, {"id": "fbc5112d-fc86-4006-af90-b7b785a31f47", "type": "topic", "title": "Crime Scene Investigation, Evidence Recognition, and Scene Safety", "description": "Teach the first point at which physical evidence can be preserved, contaminated, lost, or contextualized.", "children": [{"id": "ec12d2c8-74a4-425b-b91f-cbca4186b823", "type": "subtopic", "title": "Scene assessment and safety", "children": [{"id": "c5bdadb2-d8d7-4977-9931-59b668869c06", "type": "concept", "title": "Personal protective equipment, biohazards, sharps, chemicals, weapons, fire, structures, and environmental hazards"}, {"id": "a81a6e4a-7e5c-4f74-87ef-439f4edb1e4b", "type": "concept", "title": "Initial walk-through, scene boundaries, entry logs, command structure, and role assignments"}, {"id": "2611d31e-ca31-4cf5-9f65-4ece718852d9", "type": "concept", "title": "Victims, suspects, witnesses, bystanders, media, and multi-agency coordination"}], "description": "Crime scenes are dynamic environments where safety and triage come first."}, {"id": "154b157f-fefd-4612-9ef8-34b842165aec", "type": "subtopic", "title": "Evidence recognition", "children": [{"id": "c119354f-8e78-4b71-9ab0-0a302ac99e08", "type": "concept", "title": "Transient, conditional, pattern, transfer, biological, chemical, digital, and documentary evidence"}, {"id": "17598fdf-f587-493d-977a-545bc47ed4ee", "type": "concept", "title": "Associative evidence, source evidence, activity evidence, and reconstructive evidence"}, {"id": "08f769a3-3971-4079-aaf2-c39f51488168", "type": "concept", "title": "Search patterns, prioritization, fragile evidence, and negative evidence"}], "description": "Students learn to see potential evidence through investigative questions and scientific limits."}, {"id": "30109133-cd9d-4ac1-a79f-309d0e15f141", "type": "subtopic", "title": "Scene integrity", "children": [{"id": "922108b8-b250-4e50-a01e-fae6f11cabf4", "type": "concept", "title": "Contamination prevention, cross-transfer prevention, packaging decisions, and clean technique"}, {"id": "566eb80b-a2a8-4e4b-9643-6524653a5b97", "type": "concept", "title": "Scene security, documentation before movement, and evidence preservation"}, {"id": "ca842ad4-9a65-4ac1-8b72-daae9126275c", "type": "concept", "title": "Victim-centered practice, cultural awareness, and respectful handling"}], "description": "The point is to preserve evidence value from first response onward."}]}, {"id": "f3f8c909-5b49-4595-af2c-d4af535adb43", "type": "topic", "title": "Documentation, Photography, Mapping, Collection, Packaging, and Chain of Custody", "description": "Build the documentation habits that make evidence scientifically and legally usable.", "children": [{"id": "8dabe089-6872-413f-86fc-825b7b5ddba1", "type": "subtopic", "title": "Crime scene documentation", "children": [{"id": "46d04a95-5a29-4799-a18a-0924196eb8a8", "type": "concept", "title": "Notes, sketches, measurements, diagrams, logs, body-worn camera, and field forms"}, {"id": "4ec2cef0-2f50-4434-891f-fd318b605d50", "type": "concept", "title": "Overall, midrange, close-up, scale, oblique, alternate-light, and 360-degree photography"}, {"id": "9e71ffa2-8005-4cec-88a4-434b66b7b06c", "type": "concept", "title": "Scene mapping, total stations, laser scanners, photogrammetry, and coordinate systems"}], "description": "Documentation turns a scene into a reproducible record for later analysis."}, {"id": "a5c80579-195e-496b-9790-eb78a35736bf", "type": "subtopic", "title": "Collection and packaging", "children": [{"id": "1c6c2d6b-9b4f-4f93-957c-5575a9781123", "type": "concept", "title": "Paper, plastic, breathable packaging, swabs, envelopes, bindles, cans, vials, and tamper seals"}, {"id": "ca1281fd-4d72-4b34-831d-f56c8b20f339", "type": "concept", "title": "Wet evidence, biological evidence, trace evidence, firearms, documents, drugs, and digital devices"}, {"id": "bc4e9c42-e823-4cf6-b751-0fceac5e6cfa", "type": "concept", "title": "Labeling, seals, storage conditions, refrigeration, drying, and hazardous materials"}], "description": "Evidence must be collected in ways that preserve its analytical value."}, {"id": "002ac168-5981-42c6-979c-68661ff34235", "type": "subtopic", "title": "Chain of custody and evidence management", "children": [{"id": "b6ea196a-3044-42fc-9bd1-308dab96972f", "type": "concept", "title": "Unique identifiers, transfers, storage locations, access controls, and audit trails"}, {"id": "39d0fc3a-c928-42a4-92c7-b6eb419f92c6", "type": "concept", "title": "Laboratory information management systems and property-room procedures"}, {"id": "ad82c960-db12-4dfa-ac9b-11ea95a138dd", "type": "concept", "title": "Discovery, retention, consumption, destructive testing, and return or disposal"}], "description": "Custody records make evidence traceable and defensible."}]}, {"id": "eec5401e-358b-4198-a1ee-8286589c1999", "type": "topic", "title": "Evidence Law, Expert Testimony, Ethics, and Professional Responsibility", "description": "Connect laboratory science to courtroom admissibility and ethical communication.", "children": [{"id": "eb52b9ce-b843-4c6d-b44e-3e9de949e0df", "type": "subtopic", "title": "Evidence and admissibility", "children": [{"id": "3eb7cb03-6c1a-48fc-8d0e-8475ff28879a", "type": "concept", "title": "Federal Rules of Evidence, relevance, Rule 403, authentication, chain of custody, and hearsay issues"}, {"id": "dffdaed5-fbab-4927-88da-e9ef4c77a4b6", "type": "concept", "title": "Rule 702, expert qualifications, reliable principles and methods, and sufficient facts or data"}, {"id": "8cf04c34-a0de-48e5-8f60-c813c0687dca", "type": "concept", "title": "Daubert, Kumho Tire, Frye jurisdictions, and judicial gatekeeping"}], "description": "Students learn why scientific evidence must satisfy both relevance and reliability requirements."}, {"id": "080ee541-f950-43de-aa12-3f64ca088d29", "type": "subtopic", "title": "Expert reports and testimony", "children": [{"id": "01c4b1f3-047e-4a2a-9ead-84a32f2e167e", "type": "concept", "title": "Report structure, methods, observations, results, interpretations, limitations, and conclusions"}, {"id": "82992033-78e7-4fc6-89a2-eaf3a6a3d42c", "type": "concept", "title": "Direct examination, cross-examination, demonstratives, voir dire, and courtroom demeanor"}, {"id": "1aa47041-7593-459b-918c-f7821f8b2513", "type": "concept", "title": "Uniform language, uncertainty, alternative explanations, and avoiding source-probability overclaiming"}], "description": "The gist is to communicate findings accurately without overstating certainty."}, {"id": "94d7eea5-91a0-44e4-8ac2-d38bc01bbe5e", "type": "subtopic", "title": "Ethics and professional responsibility", "children": [{"id": "c94bb1ff-2e1e-47e1-8012-466b0a1e6bfd", "type": "concept", "title": "Objectivity, impartiality, independence, competence, documentation, and disclosure"}, {"id": "d8f489c6-fabb-4171-a896-1fde6d81ad86", "type": "concept", "title": "Cognitive bias, contextual bias, role conflict, confirmation pressure, and tunnel vision"}, {"id": "a164c740-ecfd-41d0-a16e-02ae04ac40d3", "type": "concept", "title": "Brady/Giglio obligations, corrective action, whistleblowing, and code-of-conduct expectations"}], "description": "Forensic work requires scientific integrity under adversarial pressure."}]}, {"id": "978e54a8-b06c-43f0-a022-657d7442c80b", "type": "topic", "title": "Quality Assurance, Validation, Accreditation, Standards, and Error Rates", "description": "Make reliability, reproducibility, and quality systems central rather than decorative.", "children": [{"id": "391a18d4-0137-4dbe-aa19-fa39c305a4b0", "type": "subtopic", "title": "Quality management systems", "children": [{"id": "3129bcd6-c9d1-49a8-8e8b-9aa5229899f2", "type": "concept", "title": "Policies, SOPs, training, competency, proficiency testing, audits, corrective actions, and management review"}, {"id": "0f41026c-9a92-45c9-a6a1-3df6d78520ce", "type": "concept", "title": "ISO/IEC 17025, ANAB, A2LA, accreditation scopes, and documentation control"}, {"id": "fc54e5bf-ed27-4262-b302-fa58b007c7c8", "type": "concept", "title": "LIMS, evidence tracking, reagent logs, instrument maintenance, and case review"}], "description": "Students learn how labs institutionalize reliable work."}, {"id": "575aae61-f6f6-4782-86c7-7fea8ad5ae0c", "type": "subtopic", "title": "Method validation and verification", "children": [{"id": "b7818ea1-697d-48cd-bbcb-eaaf1f0a4df4", "type": "concept", "title": "Developmental validation, internal validation, performance checks, and method limitations"}, {"id": "afad0643-96d9-4e14-a64c-afde15aa1b4e", "type": "concept", "title": "Accuracy, precision, sensitivity, specificity, robustness, reproducibility, and measurement uncertainty"}, {"id": "f729852f-de7a-466f-8f10-173046a71c4a", "type": "concept", "title": "Reference materials, controls, calibration, blank samples, and contamination monitoring"}], "description": "Methods need empirical support before they are used in casework."}, {"id": "a82a5ba3-5e1c-4efb-ada7-d610ec6890c2", "type": "subtopic", "title": "Standards and reform", "children": [{"id": "105803ed-f23c-4381-9260-b0046bb38f88", "type": "concept", "title": "NIST OSAC Registry, standards-development organizations, technical guidance, and discipline-specific standards"}, {"id": "ac7f1488-336b-4f27-ac4c-97c50cd21439", "type": "concept", "title": "National Academies and PCAST debates on validity, feature comparison, and empirical foundations"}, {"id": "a547cb99-190a-45bf-a346-78a0210f84de", "type": "concept", "title": "Implementation, transparency, lab independence, and reporting reform"}], "description": "A world-class course must confront forensic reform and standards-based practice."}]}, {"id": "ca4d47b3-8f00-4e6d-a0fe-b0e33c10ed54", "type": "topic", "title": "Latent Prints, Biometrics, and Friction Ridge Examination", "description": "Study one of the most established yet scrutiny-sensitive forensic comparison disciplines.", "children": [{"id": "8cb5939a-fe58-4d7c-8315-407aff7a5481", "type": "subtopic", "title": "Friction ridge foundations", "children": [{"id": "dc3063e8-5cf8-454d-9b6f-4aa753525350", "type": "concept", "title": "Ridge flow, minutiae, pores, distortion, substrate, deposition, and persistence"}, {"id": "8755dd7d-2d43-4dfe-b21d-ad069017db15", "type": "concept", "title": "Patent, plastic, latent, and impressed prints"}, {"id": "4d4f8c93-93c2-4852-b2a6-827b5f67d4df", "type": "concept", "title": "Biological variation, transfer mechanics, and development constraints"}], "description": "Students learn why fingerprints can be useful and what their limits are."}, {"id": "bc6be8a6-00f2-43b1-b017-4b3ef8d1a749", "type": "subtopic", "title": "Processing and comparison", "children": [{"id": "312cb1d2-2973-47e4-9a57-fd742ef61994", "type": "concept", "title": "Powders, cyanoacrylate fuming, ninhydrin, DFO, silver nitrate, alternate light, and photography"}, {"id": "55cf8a7b-0554-4fe9-a673-477345b5aea8", "type": "concept", "title": "ACE-V, sufficiency, comparison, verification, and documentation"}, {"id": "c1cdac90-96d2-4366-adb8-c27dbb897968", "type": "concept", "title": "AFIS searches, candidate lists, examiner judgment, and verification practices"}], "description": "The point is to understand the workflow from recovery to conclusion."}, {"id": "cea55cf3-69e8-4ed0-833f-9c559e3f7f3c", "type": "subtopic", "title": "Error, bias, and reporting", "children": [{"id": "38c31a8b-c31b-413b-966d-1d464306306c", "type": "concept", "title": "False positives, false negatives, inconclusive decisions, and black-box studies"}, {"id": "54a6e0ae-74c0-4eea-8cd9-fe1d3e65ef5a", "type": "concept", "title": "Context management, blind verification, sequential unmasking, and quality review"}, {"id": "a9522206-e5a5-4681-b51e-c7785b385d78", "type": "concept", "title": "Conclusion scales, source attribution, limitations, and courtroom communication"}], "description": "Latent print evidence must be framed with discipline-specific limitations."}]}, {"id": "4fcd6462-cd86-4f8a-a105-0f901a22bb00", "type": "topic", "title": "Impression Evidence, Footwear, Tires, Toolmarks, and Pattern Analysis", "description": "Teach pattern evidence while foregrounding empirical support and cautious interpretation.", "children": [{"id": "8c82f449-fcde-4159-98c9-1757bf682156", "type": "subtopic", "title": "Footwear and tire impressions", "children": [{"id": "278df1ae-a57f-4d57-ab55-301637e26e1e", "type": "concept", "title": "Class characteristics, individual characteristics, wear, damage, manufacturing variation, and databases"}, {"id": "1045b4f5-36f7-4a2b-b684-f0fb214c16f4", "type": "concept", "title": "Casting, lifting, photography, electrostatic dust lifting, and 3D documentation"}, {"id": "a6a22666-3ba8-4d54-9b2a-a61f134c759a", "type": "concept", "title": "Scene-to-known comparisons, exclusion, association, and limitations"}], "description": "Impression evidence can link people, vehicles, places, and events when properly documented."}, {"id": "077c1e24-6442-4e2d-a1eb-e60d149690c9", "type": "subtopic", "title": "Toolmarks and fracture matches", "children": [{"id": "e7b4c873-6e4f-4411-8827-f6144f06abac", "type": "concept", "title": "Striated and impressed toolmarks, cutting tools, pry marks, and manufacturing marks"}, {"id": "6b6c616c-6b4a-4883-9710-8d72dbc1ad2d", "type": "concept", "title": "Physical fit, fracture match, comparison microscopy, and documentation"}, {"id": "bc0770f1-3c5c-4d5f-8eaf-d8f0240d986e", "type": "concept", "title": "Subclass characteristics, reproducibility, and alternative sources"}], "description": "Toolmark work examines how objects produce marks and whether separated items once fit together."}, {"id": "bd1fa6c3-888e-4686-8552-2c8adb35b65d", "type": "subtopic", "title": "Pattern evidence discipline", "children": [{"id": "97d3a7c9-47e4-41cb-8e63-7ad247d2792b", "type": "concept", "title": "Subjective interpretation, cognitive bias, base rates, validation studies, and examiner training"}, {"id": "76821480-2e52-452b-99de-36049325cfc4", "type": "concept", "title": "Quality assurance, verification, consensus review, and error studies"}, {"id": "996f6ac1-e309-4962-b7fa-1024caea23d4", "type": "concept", "title": "Probative value, demonstratives, and careful reporting language"}], "description": "Students learn common risks across pattern disciplines."}]}, {"id": "7531e4eb-1aa2-4bce-8e93-176d2bdffedb", "type": "topic", "title": "Trace Evidence: Hair, Fibers, Glass, Paint, Polymers, Soil, and GSR", "description": "Use small-material evidence to teach transfer, persistence, analytical chemistry, and cautious source inference.", "children": [{"id": "e47a653d-be40-44a6-abb0-23bbcb87bf02", "type": "subtopic", "title": "Transfer and persistence", "children": [{"id": "bde34ec5-27e2-47b5-ae09-de9585972f92", "type": "concept", "title": "Locard exchange, primary transfer, secondary transfer, persistence, loss, contamination, and background levels"}, {"id": "85626ab2-29e3-4ea7-a513-1a9e2b3b7529", "type": "concept", "title": "Collection by tape lift, scraping, vacuuming, picking, and packaging"}, {"id": "70934cde-0753-483b-9467-7a4c9c976584", "type": "concept", "title": "Activity-level versus source-level propositions"}], "description": "Trace evidence starts with how materials move, remain, degrade, and are recovered."}, {"id": "e5a88b2b-d148-4931-9275-3473c5d043ab", "type": "subtopic", "title": "Microscopy and instrumental analysis", "children": [{"id": "ec7bd38a-d415-45b6-bf36-2325b7f0a3f6", "type": "concept", "title": "Stereomicroscopy, comparison microscopy, polarized light microscopy, and fluorescence microscopy"}, {"id": "a9e40580-ce16-472e-9c4a-4db8889e10e2", "type": "concept", "title": "FTIR, Raman, SEM-EDS, XRF, ICP-MS, GC-MS, and pyrolysis GC-MS"}, {"id": "2304271d-f5ad-4e0b-a1dd-ec9ebfadf1ad", "type": "concept", "title": "Class characteristics, discrimination, databases, and reference collections"}], "description": "Students learn the laboratory tools used to characterize trace materials."}, {"id": "a15776ec-a361-4827-a55e-c8f933a5620e", "type": "subtopic", "title": "Trace interpretation", "children": [{"id": "8e51fe8c-0257-43fc-865f-146e10b75e04", "type": "concept", "title": "Hair microscopy and limits, fiber comparison, glass refractive index, paint layer sequences, and soil mineralogy"}, {"id": "c5267546-06a4-47bb-a853-1cb5fc9efc6c", "type": "concept", "title": "Gunshot residue particles, environmental sources, persistence, and transfer"}, {"id": "0a26e9a1-04ea-4e9f-b9e7-e4acad5582a8", "type": "concept", "title": "Likelihood, alternative explanations, and investigative use"}], "description": "The gist is to report evidence value without pretending class evidence is unique."}]}, {"id": "8da63894-bbc8-4e89-a249-e52d901337ae", "type": "topic", "title": "Forensic Biology, Serology, Biological Fluids, and DNA Screening", "description": "Introduce biological evidence before advanced DNA interpretation.", "children": [{"id": "947bbbb0-a68b-40ee-bfbe-c3e84a1330fa", "type": "subtopic", "title": "Biological evidence recognition", "children": [{"id": "33fa3c08-62b9-4dcf-9b18-f9ec499769a6", "type": "concept", "title": "Blood, semen, saliva, epithelial cells, tissue, bone, teeth, hair roots, and touch DNA"}, {"id": "224f5bd0-f0bf-4487-819b-44653a4aa035", "type": "concept", "title": "Presumptive tests, confirmatory tests, microscopy, alternate light sources, and species testing"}, {"id": "18f5497e-809c-493c-ba88-7364b0b0d500", "type": "concept", "title": "Contamination controls, collection strategies, and degradation"}], "description": "Students learn how biological materials are found, preserved, and screened."}, {"id": "c24dc459-9fcd-4ae0-8c9e-cbd52ffcf1fc", "type": "subtopic", "title": "Serology and body-fluid testing", "children": [{"id": "e897584a-2f3e-44cf-bfeb-e30ac107b3be", "type": "concept", "title": "Kastle-Meyer, luminol, Bluestar, ABAcard, acid phosphatase, PSA, RSID tests, and amylase"}, {"id": "08c05f4d-d73b-4b05-97f9-ea1d6cf1323f", "type": "concept", "title": "False positives, sensitivity, specificity, inhibitors, substrates, and environmental effects"}, {"id": "b33a74d0-0dd8-45ea-b6da-b64546a40093", "type": "concept", "title": "Screening documentation, consumption decisions, and triage"}], "description": "Serology gives investigative and probative context even before DNA profiling."}, {"id": "fa2b05d5-7fd4-4788-8b4a-51f4b25a6e35", "type": "subtopic", "title": "DNA workflow foundations", "children": [{"id": "ebec3d34-9fda-4893-b801-bc8fda1ba858", "type": "concept", "title": "Extraction, quantitation, amplification, STR typing, capillary electrophoresis, and allele calling"}, {"id": "5e3645f5-31d7-4034-88f1-391f017e4c24", "type": "concept", "title": "Controls, contamination monitoring, degradation, inhibition, stochastic effects, and low-template DNA"}, {"id": "db1a7694-4c2f-44ae-ad99-1f697b710732", "type": "concept", "title": "Reference samples, elimination samples, databases, and CODIS context"}], "description": "Students learn the pipeline from sample to profile."}]}, {"id": "19f7f1ef-d196-4b5c-9cfb-aeb4f0d1b42c", "type": "topic", "title": "Forensic DNA Analysis, Mixtures, Kinship, Databases, and Genetic Genealogy", "description": "Develop world-class DNA literacy, including interpretation, statistics, and ethical constraints.", "children": [{"id": "3e2d53b8-95fe-4788-b768-0eb681de52f2", "type": "subtopic", "title": "STR profiles and interpretation", "children": [{"id": "6c5e42cf-e311-4704-8806-259dab2556c0", "type": "concept", "title": "Autosomal STRs, Y-STRs, mtDNA, SNPs, probabilistic genotyping, and sequence data"}, {"id": "7c968ac9-3684-4d00-8856-c0418388e3b3", "type": "concept", "title": "Single-source profiles, mixtures, contributors, peak height, stutter, drop-in, and drop-out"}, {"id": "7248d077-0868-40d7-a03a-678e5a97593d", "type": "concept", "title": "Interpretation thresholds, validation, software, and analyst review"}], "description": "Students learn how DNA profiles become conclusions."}, {"id": "56d8227a-03f9-4ff5-bec2-596e1bc29346", "type": "subtopic", "title": "Statistics and database use", "children": [{"id": "2e1c7e74-ddb0-47de-a59c-d3298cd01329", "type": "concept", "title": "Random match probability, likelihood ratios, population databases, substructure, and relatedness"}, {"id": "f3e9b7aa-245e-411f-b5ca-c29f0012f540", "type": "concept", "title": "CODIS eligibility, database hits, familial searching, and confirmation"}, {"id": "ad88e274-d836-4799-97db-842a3c093844", "type": "concept", "title": "Probative value, prosecutor's fallacy, defense fallacy, and communication"}], "description": "DNA evidence is powerful because it is paired with transparent statistical reasoning."}, {"id": "0e9515b5-a6db-4040-9276-693a39d8badc", "type": "subtopic", "title": "Forensic genetic genealogy", "children": [{"id": "3e413230-8ea3-41b1-8dc7-42dbfa00cf26", "type": "concept", "title": "SNP profiles, genealogy databases, lead generation, kinship trees, and confirmation by STR testing"}, {"id": "6b6a7010-4523-4bc2-b504-dda4ac289c8a", "type": "concept", "title": "DOJ interim policy, consent, privacy, scope, violent-crime limits, and oversight"}, {"id": "ef6a4ebc-23b7-4cf6-ac78-a6ea0a8a2a7c", "type": "concept", "title": "Ethics, community impact, exonerations, cold cases, and transparency"}], "description": "Students learn the promise and risk of investigative genealogy."}]}, {"id": "c06a7b4c-ec79-41f7-a8d1-ee7d6530dd76", "type": "topic", "title": "Forensic Toxicology, Drugs, Alcohol, Poisons, and Impaired Driving", "description": "Connect chemistry, biology, pharmacology, and legal standards.", "children": [{"id": "f9c47363-c509-4fbd-a1bd-4c1e7be123cd", "type": "subtopic", "title": "Toxicology foundations", "children": [{"id": "dee8bdc0-bc02-42df-b157-8c128120cd55", "type": "concept", "title": "Dose, route, absorption, distribution, metabolism, elimination, tolerance, and impairment"}, {"id": "c86786dd-73c3-449e-8fff-7b1c380d55a9", "type": "concept", "title": "Blood, urine, oral fluid, vitreous, hair, tissue, and postmortem redistribution"}, {"id": "34598c24-5df2-4f13-b861-61bd2473fa25", "type": "concept", "title": "Therapeutic, toxic, lethal, and interpretive concentration ranges"}], "description": "Students learn how substances enter, move through, and affect the body."}, {"id": "7562ccb7-00ec-4755-b21c-57f7b81bde14", "type": "subtopic", "title": "Analytical toxicology", "children": [{"id": "5e048cce-787d-4312-91bb-bde411658295", "type": "concept", "title": "Immunoassay, color tests, GC-MS, LC-MS/MS, headspace GC, and calibration"}, {"id": "9e7c416a-c857-4e9c-922a-cb51ee253d0d", "type": "concept", "title": "Controls, standards, matrix effects, limits of detection, limits of quantitation, and validation"}, {"id": "4d207a76-0dbd-4f69-b623-8c5903ea0b0c", "type": "concept", "title": "Alcohol, opioids, benzodiazepines, stimulants, cannabinoids, and new psychoactive substances"}], "description": "The point is to understand screening, confirmation, quantitation, and uncertainty."}, {"id": "1794d0ea-7ce4-4f23-aec2-152e777b82d2", "type": "subtopic", "title": "Legal and interpretive contexts", "children": [{"id": "d52d8c87-2528-468d-8ad4-f78c3cf28eb9", "type": "concept", "title": "DUI/DWI, drug-facilitated crime, overdose, poisoning, workplace testing, and death investigation"}, {"id": "d95d231c-4626-4d50-bf67-083782d2b12a", "type": "concept", "title": "Impairment versus presence, timing, tolerance, poly-drug effects, and retrograde extrapolation"}, {"id": "6249dbde-517e-4e8e-adb2-4ca350015a47", "type": "concept", "title": "Expert testimony, uncertainty, and public-health context"}], "description": "Toxicology evidence is used differently across case types."}]}, {"id": "ae1ca9da-0f88-47f7-aa1a-053074827f5f", "type": "topic", "title": "Forensic Chemistry: Controlled Substances, Fire Debris, Explosives, and Unknowns", "description": "Use chemical analysis to identify substances and reconstruct chemical events.", "children": [{"id": "4be3f07c-b218-49d3-8d82-94e66da7a1c2", "type": "subtopic", "title": "Controlled substance analysis", "children": [{"id": "e41a776d-e007-45a8-9fd4-4338e822ae34", "type": "concept", "title": "Sampling, weighing, presumptive tests, microscopy, FTIR, Raman, GC-MS, LC-MS, and reference standards"}, {"id": "9cb9bc81-4ac6-4463-bf05-807dba70c324", "type": "concept", "title": "Seized drugs, tablets, powders, plant material, vapes, and mixtures"}, {"id": "14d80b25-f8b5-4649-b683-6aa56ed0619d", "type": "concept", "title": "Scheduling, analogues, uncertainty, and reporting"}], "description": "Students learn how unknown drug evidence is characterized and confirmed."}, {"id": "df1fca24-2c54-49e5-ac7c-944bac4228a1", "type": "subtopic", "title": "Fire debris and ignitable liquids", "children": [{"id": "dfee7e93-1647-454c-a760-332838b7cc84", "type": "concept", "title": "Sample collection, containers, headspace concentration, GC-MS, and ignitable liquid classification"}, {"id": "c0728646-919f-4e6e-a1f2-80a75b3f84d9", "type": "concept", "title": "Pyrolysis products, substrate interference, weathering, and comparison to references"}, {"id": "6ee263bd-2942-4e30-bc8e-2f53c1697c2b", "type": "concept", "title": "Arson investigation, accidental fires, electrical causes, and scene context"}], "description": "Fire debris analysis connects chemistry with origin-and-cause investigation."}, {"id": "225b3818-8bac-44db-b123-f5e46e927fd5", "type": "subtopic", "title": "Explosives and unknown hazardous materials", "children": [{"id": "5a2b41ac-74e1-4215-b61b-089084062c73", "type": "concept", "title": "Explosive residues, oxidizers, organic explosives, inorganic ions, and post-blast debris"}, {"id": "555ca5c4-1e10-4864-9b86-1ce683ec01da", "type": "concept", "title": "Ion chromatography, Raman, FTIR, SEM-EDS, GC-MS, and LC-MS"}, {"id": "2c4057bf-b2bf-4617-b13f-483a181ed44a", "type": "concept", "title": "Safety, triage, field screening, and interagency coordination"}], "description": "Students learn safe handling and analysis of energetic or suspicious materials."}]}, {"id": "e28c2f2b-5c8f-47d3-86ea-3780fa02bcd9", "type": "topic", "title": "Firearms, Ballistics, Toolmarks, Gunshot Residue, and Shooting Reconstruction", "description": "Teach firearms evidence from safety and documentation through comparison and reconstruction.", "children": [{"id": "eef446af-f679-432e-974c-c53353250ef2", "type": "subtopic", "title": "Firearms foundations", "children": [{"id": "b63c4f1f-072d-4b07-8f91-3d13c22e01e6", "type": "concept", "title": "Handguns, rifles, shotguns, cartridges, bullets, casings, primers, and gunpowder"}, {"id": "cbed3ced-954b-4d15-bfcb-96027e5f0631", "type": "concept", "title": "Firearm safety, operability, test fires, muzzle-to-target distance, and serial-number restoration"}, {"id": "4b18fbd6-5066-41ce-ba62-098a379fe86f", "type": "concept", "title": "NIBIN, IBIS, reference collections, and lab workflow"}], "description": "Students learn firearm types, ammunition components, and evidence handling."}, {"id": "c9f93ec2-1c5b-4a43-8c54-ababfec21409", "type": "subtopic", "title": "Comparison and interpretation", "children": [{"id": "26751333-33bb-4256-a30e-8d2ef7bb0c20", "type": "concept", "title": "Class characteristics, rifling, breech face marks, firing pin marks, extractor marks, and ejector marks"}, {"id": "1f8060c9-742b-49eb-b4aa-af7005122632", "type": "concept", "title": "Comparison microscopy, toolmark reproducibility, subclass characteristics, and verification"}, {"id": "5e671dab-5062-429e-a0b5-31d4c65acf54", "type": "concept", "title": "Conclusion scales, error studies, and courtroom communication"}], "description": "Firearm comparison requires careful attention to empirical limits."}, {"id": "9555ddb2-5a1c-4934-ada0-7f9f74c7bf61", "type": "subtopic", "title": "Shooting reconstruction", "children": [{"id": "e63fb44a-c7f2-4317-9ec6-c3083a49346d", "type": "concept", "title": "Trajectory, bullet holes, defects, ricochet, spatter, stippling, soot, and GSR"}, {"id": "521502a3-bd17-470b-bb7f-5e9060caa773", "type": "concept", "title": "Scene diagrams, rods, lasers, stringing, photography, and 3D methods"}, {"id": "63986ce9-6b28-4ac2-8159-90e758889774", "type": "concept", "title": "Limitations, alternative scenarios, and integrated reporting"}], "description": "Shooting cases integrate scene, medical, and physical evidence."}]}, {"id": "5404cc84-2718-4d1b-8818-acab20bab407", "type": "topic", "title": "Questioned Documents, Handwriting, Ink, Paper, and Fraudulent Documents", "description": "Study document evidence as both physical material and communication artifact.", "children": [{"id": "9ca564e1-4699-4fdb-b56d-a726b7b2d6c6", "type": "subtopic", "title": "Document examination foundations", "children": [{"id": "1b08d80a-e002-4893-97b8-edb667d38f17", "type": "concept", "title": "Handwriting, signatures, indented writing, alterations, erasures, obliterations, and sequence of strokes"}, {"id": "8ecfaeba-250d-4b0f-b219-8b4f36eea452", "type": "concept", "title": "Typewriters, printers, photocopiers, scanners, and digital printing artifacts"}, {"id": "9c5a9ba5-a36e-4dfa-87e5-a8f54d65b401", "type": "concept", "title": "Standards, exemplars, known writings, request writings, and natural variation"}], "description": "Students learn how documents can reveal authorship, alteration, or production history."}, {"id": "97bff601-4bf9-4882-8df7-6fd2d6222f7c", "type": "subtopic", "title": "Ink, paper, and physical document analysis", "children": [{"id": "58558a8a-05e9-4730-b9bf-832dfbad0c59", "type": "concept", "title": "Ink chemistry, TLC, Raman, IR, microspectrophotometry, paper fibers, watermarks, and security features"}, {"id": "24da335a-53e5-4674-9365-bfce42c88a8f", "type": "concept", "title": "Currency, IDs, passports, checks, contracts, wills, and anonymous letters"}, {"id": "fe70f3a7-6b3b-4f3f-a117-4a34ff6ef0f2", "type": "concept", "title": "Aging limits, environmental effects, and destructive testing"}], "description": "Material analysis can support or limit document conclusions."}, {"id": "0e3f8c35-73de-4900-9db8-1a475faa683e", "type": "subtopic", "title": "Reporting and testimony", "children": [{"id": "83502f4e-41ee-424f-a47b-2067ef899a79", "type": "concept", "title": "Opinion scales, limitations, uncertainty, and alternative explanations"}, {"id": "0376fb4a-9b9d-4c28-b2fd-31201f8f6300", "type": "concept", "title": "Authentication, best evidence, chain of custody, and demonstratives"}, {"id": "c631510b-a3c0-44e7-8b53-b5c081395d95", "type": "concept", "title": "Digital-document overlap, metadata, and fraud investigations"}], "description": "Questioned document work requires clear distinction between observation and opinion."}]}, {"id": "6d0d1593-cd0e-429d-9403-1282aafd45e7", "type": "topic", "title": "Digital, Multimedia, Mobile Device, and Cyber-Physical Evidence", "description": "Add the modern evidence stream that appears in nearly every investigation.", "children": [{"id": "35bee364-1c22-496a-9804-8868a954fcea", "type": "subtopic", "title": "Digital evidence foundations", "children": [{"id": "899428eb-6b33-44c0-91ff-0329b2fe759e", "type": "concept", "title": "Volatility, metadata, logs, timestamps, file systems, cloud data, and network artifacts"}, {"id": "7ca22b13-f62e-4686-9829-2aff5d901b0d", "type": "concept", "title": "Forensic imaging, hashing, write blockers, preservation, and chain of custody"}, {"id": "37aa0c98-95be-4a7b-8f7e-3ba186fb2e42", "type": "concept", "title": "Legal process, warrants, consent, scope, and privacy"}], "description": "Students learn how digital evidence differs from physical evidence."}, {"id": "82026987-9bd7-446a-ba9f-862ed390f824", "type": "subtopic", "title": "Device and multimedia forensics", "children": [{"id": "4a511ba1-9549-484b-b7bc-12231dd083bc", "type": "concept", "title": "Mobile extraction, app data, location data, messages, browser history, and deleted files"}, {"id": "95b8996f-4a06-4bd4-a84f-5a2be71f771a", "type": "concept", "title": "Video authentication, enhancement limits, compression artifacts, and frame analysis"}, {"id": "af0298a6-1ed4-4e21-b873-fee0dce50e5e", "type": "concept", "title": "Audio, images, deepfakes, body cameras, surveillance systems, and drones"}], "description": "Digital evidence often arrives as phones, video, images, and audio."}, {"id": "8b2d8148-a137-49f2-897f-2639cdd7f82f", "type": "subtopic", "title": "Cyber-physical investigations", "children": [{"id": "160c6e96-3732-4f59-a3ac-3aa5fc9d8477", "type": "concept", "title": "Vehicle infotainment, IoT, wearables, smart homes, access control, and industrial systems"}, {"id": "e5c62435-eab3-4856-9aa6-c587178e9f8e", "type": "concept", "title": "Malware, intrusion artifacts, exfiltration, and attribution limits"}, {"id": "97a39652-20b9-433b-8dab-579db424cb31", "type": "concept", "title": "Documentation, repeatability, tool validation, and expert communication"}], "description": "Forensics increasingly bridges devices, networks, and physical events."}]}, {"id": "d7964b08-a5d5-4a12-84ea-75e3c9b7106d", "type": "topic", "title": "Death Investigation, Forensic Pathology, Anthropology, Odontology, and Entomology", "description": "Give criminalistics students enough medicolegal context to understand death-related evidence.", "children": [{"id": "541c03cc-6028-4403-b8f0-6a0de92d36d3", "type": "subtopic", "title": "Medicolegal death investigation", "children": [{"id": "bf73571a-6480-4cd0-9451-2612ea6dec97", "type": "concept", "title": "Cause, manner, mechanism, time of death, and circumstances"}, {"id": "8a01ece2-b979-44b4-96ed-4626b81e0df3", "type": "concept", "title": "Coroner versus medical examiner systems, scene attendance, autopsy, and death certificates"}, {"id": "c7dd41ee-655b-45ab-bbc5-68d3dcf31960", "type": "concept", "title": "Sudden, violent, suspicious, custodial, child, and unattended deaths"}], "description": "Students learn how deaths are classified and investigated in U.S. systems."}, {"id": "318fda23-823c-4e91-a2d2-018be52ce487", "type": "subtopic", "title": "Forensic pathology and anthropology", "children": [{"id": "42943f52-7497-408d-afc1-922cc17a82b0", "type": "concept", "title": "Injury interpretation, blunt force, sharp force, gunshot wounds, asphyxia, burns, and decomposition"}, {"id": "e9b1e2d5-b5b6-45ff-b467-2035452fb8b6", "type": "concept", "title": "Human versus nonhuman remains, biological profile, trauma, taphonomy, and commingled remains"}, {"id": "15d88d3a-8810-49ab-a866-bece5847f3d0", "type": "concept", "title": "Mass disasters, missing persons, NamUs, and humanitarian identification"}], "description": "Death investigation often requires biological and skeletal expertise."}, {"id": "eb369f2a-8874-486e-b274-a98d64e58e55", "type": "subtopic", "title": "Odontology, entomology, and interdisciplinary evidence", "children": [{"id": "68f194c1-5cef-4908-b622-be54c9206697", "type": "concept", "title": "Dental identification, bite mark controversy, dental records, and limitations"}, {"id": "41c99394-f11f-4172-97dd-d191d9737a57", "type": "concept", "title": "Insect succession, accumulated degree days, and postmortem interval estimates"}, {"id": "2d0fdb60-bec0-4ddc-8d8c-aa3143ee4623", "type": "concept", "title": "Integrated case review across scene, lab, medical, and investigative evidence"}], "description": "Specialty disciplines contribute when remains or scenes present specific questions."}]}, {"id": "9c6b8083-b090-4f78-9956-e3042d8e9eb7", "type": "topic", "title": "Forensic Statistics, Probabilistic Reasoning, Cognitive Bias, and Evidence Interpretation", "description": "Make quantitative reasoning and bias control part of every forensic conclusion.", "children": [{"id": "cf2d2aae-bba8-4b7f-8a74-f206f864a452", "type": "subtopic", "title": "Probability and evidentiary reasoning", "children": [{"id": "6a99a829-a8af-4735-a420-b8cdc8fe6c2c", "type": "concept", "title": "Sensitivity, specificity, false positives, false negatives, base rates, and uncertainty"}, {"id": "d4324118-8ba4-419b-9daa-962131bb584a", "type": "concept", "title": "Likelihood ratios, random match probabilities, Bayesian reasoning, and activity-level propositions"}, {"id": "c43473d4-83ff-4bff-95cb-07050f4f863f", "type": "concept", "title": "Prosecutor's fallacy, defense fallacy, and source-versus-activity interpretation"}], "description": "Students learn to reason about evidence strength without overclaiming."}, {"id": "f08c631c-5c7e-4305-ba29-10eeffbdb5c6", "type": "subtopic", "title": "Cognitive bias and human factors", "children": [{"id": "8bd0438d-f58d-474b-ba31-cbde82a0e17c", "type": "concept", "title": "Contextual bias, confirmation bias, role effects, anchoring, task-irrelevant information, and sequential unmasking"}, {"id": "85f9b88d-2dee-43cf-959e-53f63bf80b75", "type": "concept", "title": "Blind verification, linear sequential unmasking, case triage, and quality review"}, {"id": "f1320104-0fa6-467a-b94f-0a675a11a81a", "type": "concept", "title": "Human factors research, ergonomics, fatigue, workload, and lab culture"}], "description": "Forensic conclusions are shaped by people and systems."}, {"id": "dd33ec32-a06e-4207-8f61-a1cc06af916c", "type": "subtopic", "title": "Communication of limitations", "children": [{"id": "df378465-0ef7-4e27-b305-7fd70104b67d", "type": "concept", "title": "Conclusion scales, verbal qualifiers, likelihood ratios, charts, and demonstratives"}, {"id": "d2031ead-3980-48a3-976f-9ae8f16e76d6", "type": "concept", "title": "Uncertainty, method limits, validation boundaries, and alternative hypotheses"}, {"id": "38a11eb6-e110-4e7c-844b-414dda340090", "type": "concept", "title": "Report writing, testimony, cross-examination, and public understanding"}], "description": "The most honest conclusion is one that explains what evidence can and cannot say."}]}, {"id": "0c3edd7d-0419-4b70-9f58-74d812abdd80", "type": "topic", "title": "Integrated Criminalistics Capstone: Casework, Laboratory Workflow, Reporting, and Courtroom Presentation", "description": "Synthesize the course in a realistic case file from scene through lab analysis and testimony.", "children": [{"id": "f9aab48b-38c4-47d3-9636-98b59c3c6791", "type": "subtopic", "title": "Case-file triage", "children": [{"id": "9bcef489-e8f7-4a12-b781-084491f5a049", "type": "concept", "title": "Scene notes, evidence inventory, lab requests, chain of custody, and investigative questions"}, {"id": "d2efaed0-b1eb-4bc7-ba2d-fc3ab3a8459b", "type": "concept", "title": "Testing sequence, consumption risk, preservation, defense access, and discovery"}, {"id": "8bce1185-3190-4b73-8d65-b776990d7031", "type": "concept", "title": "Prioritization, backlogs, communication, and stakeholder expectations"}], "description": "Students practice selecting methods based on evidence, case theory, and resource limits."}, {"id": "defe7c99-a834-42f9-abca-0bd0f16c3d7a", "type": "subtopic", "title": "Integrated lab report", "children": [{"id": "2470a35a-99ad-4f48-bf9c-a40eb7435a3b", "type": "concept", "title": "Methods, observations, results, interpretations, limitations, and technical review"}, {"id": "b5a6891c-2c15-418f-ba38-a83124bff415", "type": "concept", "title": "Cross-discipline integration without overstating connections"}, {"id": "b6b50aa3-3949-4fc6-b424-50b8e2239781", "type": "concept", "title": "Quality review, corrective action, and final report release"}], "description": "The capstone turns scientific results into defensible written work product."}, {"id": "1632240c-843c-40c2-b55c-eef76dde7873", "type": "subtopic", "title": "Courtroom and policy presentation", "children": [{"id": "219dec8f-6dd1-49cc-addb-ca2d52f1de47", "type": "concept", "title": "Expert qualification, direct examination, cross-examination, demonstratives, and plain-language testimony"}, {"id": "64d4af97-f6d3-42d6-845d-4eedb1e54674", "type": "concept", "title": "Ethics, uncertainty, Brady/Giglio, discovery, and adversarial pressure"}, {"id": "e679ba08-aa09-4464-8096-c01eca428ea2", "type": "concept", "title": "Policy recommendations for lab quality, standards implementation, and forensic reform"}], "description": "Students learn to explain science to legal and public audiences."}]}], "dbBacked": true}$fscrjson$::jsonb,
  true,
